// 格式化店铺名为 AMZ 格式（输入时补全前缀用）
function formatShopName(name: string): string {
  const trimmed = name.trim();
  if (!trimmed) return '';
  // 如果已经是 AMZ 开头，直接返回
  if (/^AMZ\s/.test(trimmed)) return trimmed;
  // 如果包含「亚马逊」，转换为 AMZ 格式
  if (trimmed.includes('亚马逊')) {
    const site = trimmed.replace(/亚马逊/, '').replace(/站$/, '').trim();
    return `AMZ ${site || '主'}店`;
  }
  // 其他情况，加上 AMZ 前缀
  return `AMZ ${trimmed}`;
}

// 旧格式店铺名 → AMZ 格式的显示归一化（仅用于展示/筛选，不改存储数据）
// 兼容：亚马逊美国站 / 亚马逊欧洲站 / 亚马逊日本站 等旧式命名
function normalizeShopForDisplay(shop: string): string {
  const trimmed = shop?.trim() || '';
  if (!trimmed) return trimmed;
  // 已经是 AMZ 格式，直接返回
  if (/^AMZ[\s／]/i.test(trimmed)) return trimmed;
  // 旧式亚马逊站点名：亚马逊XX站 / 亚马逊XX
  const amzMatch = trimmed.match(/^亚马逊(.+?)(站|店)?$/);
  if (amzMatch) {
    const site = amzMatch[1].trim();
    return `AMZ ${site}店`;
  }
  return trimmed;
}

