// 计算时效（下单→到货 总天数）
function calcLeadDays(orderedAt: string, arrivedAt?: string): number | null {
  if (!arrivedAt) return null;
  const start = new Date(orderedAt).getTime();
  const end = new Date(arrivedAt).getTime();
  if (isNaN(start) || isNaN(end)) return null;
  return Math.round((end - start) / (1000 * 60 * 60 * 24) * 10) / 10;
}

// ==================== 跨境订单时效异常检测 ====================

interface LeadTimeAbnormalRecord {
  type: AbnormalType;
  record: LeadTimeRecord;
  triggerInfo: string;
  suggestion: string;
}

function detectLeadTimeAbnormalRecords(records: LeadTimeRecord[]): LeadTimeAbnormalRecord[] {
  const results: LeadTimeAbnormalRecord[] = [];
  const arrived = (r: LeadTimeRecord) => !!r.arrivedAt;

  records.forEach((record) => {
    const leadDays = calcLeadDays(record.orderedAt, record.arrivedAt);

    // 1. 运输超 7 天：已到货且时效 > 7 天，或未到货且已超过 7 天
    if (leadDays !== null && leadDays > 7) {
      results.push({
        type: 'shipping_delay',
        record,
        triggerInfo: `实际时效 ${leadDays} 天`,
        suggestion: ABNORMAL_SUGGESTIONS.shipping_delay,
      });
    } else if (!record.arrivedAt) {
      const daysSinceOrder = Math.floor((Date.now() - new Date(record.orderedAt).getTime()) / (1000 * 60 * 60 * 24));
      if (daysSinceOrder > 7) {
        results.push({
          type: 'shipping_delay',
          record,
          triggerInfo: `已下单 ${daysSinceOrder} 天未到货`,
          suggestion: ABNORMAL_SUGGESTIONS.shipping_delay,
        });
      }
    }

    // 2. 到库破损
    if (arrived(record) && record.arrivalQuality === 'damaged') {
      results.push({
        type: 'arrival_damaged',
        record,
        triggerInfo: '到货质检：破损',
        suggestion: ABNORMAL_SUGGESTIONS.arrival_damaged,
      });
    }

    // 3. 到库瑕疵
    if (arrived(record) && record.arrivalQuality === 'defective') {
      results.push({
        type: 'arrival_defective',
        record,
        triggerInfo: '到货质检：瑕疵',
        suggestion: ABNORMAL_SUGGESTIONS.arrival_defective,
      });
    }

    // 4. 数量漏件
    if (arrived(record) && record.arrivalQuality === 'missing') {
      results.push({
        type: 'quantity_missing',
        record,
        triggerInfo: '到货质检：漏件',
        suggestion: ABNORMAL_SUGGESTIONS.quantity_missing,
      });
    }
  });

  return results;
}

function computeLeadTimeAbnormalStats(records: LeadTimeAbnormalRecord[]) {
  return {
    total: records.length,
    shippingDelay: records.filter((r) => r.type === 'shipping_delay').length,
    damaged: records.filter((r) => r.type === 'arrival_damaged').length,
    defective: records.filter((r) => r.type === 'arrival_defective').length,
    missing: records.filter((r) => r.type === 'quantity_missing').length,
  };
}

// ==================== 时效趋势数据计算 ====================

function getRecentDays(n: number): string[] {
  const result: string[] = [];
  const today = new Date();
  for (let i = n - 1; i >= 0; i--) {
    const d = new Date(today);
    d.setDate(today.getDate() - i);
    result.push(d.toISOString().slice(0, 10));
  }
  return result;
}

interface LeadTimeTrendItem {
  date: string;
  avgDays: number | null;
  count: number;
}

function calcLeadTimeTrend(records: LeadTimeRecord[], days: number): LeadTimeTrendItem[] {
  const dateList = getRecentDays(days);
  const arrivedRecords = records.filter((r) => r.arrivedAt);

  return dateList.map((date) => {
    const dayRecords = arrivedRecords.filter((r) => r.arrivedAt === date);
    const count = dayRecords.length;
    if (count === 0) {
      return { date, avgDays: null, count: 0 };
    }
    const totalDays = dayRecords.reduce((sum, r) => {
      const d = calcLeadDays(r.orderedAt, r.arrivedAt);
      return sum + (d ?? 0);
    }, 0);
    return {
      date,
      avgDays: Math.round((totalDays / count) * 10) / 10,
      count,
    };
  });
}

// ==================== 时效建议生成 ====================

interface LeadTimeSuggestion {
  type: 'warning' | 'info' | 'success';
  icon: 'trending-up' | 'trending-down' | 'zap' | 'target' | 'lightbulb';
  title: string;
  content: string;
}

function generateLeadTimeSuggestions(records: LeadTimeRecord[]): LeadTimeSuggestion[] {
  const suggestions: LeadTimeSuggestion[] = [];
  const arrivedRecords = records.filter((r) => r.arrivedAt);

  if (arrivedRecords.length === 0) {
    return suggestions;
  }

  // 计算整体平均时效
  const totalDays = arrivedRecords.reduce((sum, r) => {
    const d = calcLeadDays(r.orderedAt, r.arrivedAt);
    return sum + (d ?? 0);
  }, 0);
  const avgDays = Math.round((totalDays / arrivedRecords.length) * 10) / 10;

  // 建议1：整体时效评估
  if (avgDays > 15) {
    suggestions.push({
      type: 'warning',
      icon: 'trending-up',
      title: `平均时效偏长（${avgDays}天）`,
      content: '整体订单平均时效超过15天，建议关注物流商服务质量，考虑更换更快的物流渠道或货代；同时可与供应商协商缩短发货周期。',
    });
  } else if (avgDays > 7) {
    suggestions.push({
      type: 'info',
      icon: 'lightbulb',
      title: `平均时效 ${avgDays} 天`,
      content: '时效处于正常偏高水平，建议持续监控核心物流渠道表现，旺季前提前备货以应对可能的延误。',
    });
  } else {
    suggestions.push({
      type: 'success',
      icon: 'zap',
      title: `时效良好（平均${avgDays}天）`,
      content: '当前订单时效表现优秀，建议保持现有物流渠道和供应商合作，并可尝试将优秀渠道的经验复制到其他品类。',
    });
  }

  // 建议2：按平台分析
  const platformMap = new Map<string, { total: number; days: number }>();
  arrivedRecords.forEach((r) => {
    const d = calcLeadDays(r.orderedAt, r.arrivedAt) ?? 0;
    const curr = platformMap.get(r.platform) ?? { total: 0, days: 0 };
    platformMap.set(r.platform, { total: curr.total + 1, days: curr.days + d });
  });

  let slowestPlatform = '';
  let slowestDays = 0;
  platformMap.forEach((v, k) => {
    const avg = v.days / v.total;
    if (avg > slowestDays && v.total >= 2) {
      slowestDays = avg;
      slowestPlatform = k;
    }
  });

  if (slowestPlatform && slowestDays > 10) {
    suggestions.push({
      type: 'warning',
      icon: 'target',
      title: `${slowestPlatform} 时效偏长`,
      content: `${slowestPlatform} 渠道平均时效约 ${Math.round(slowestDays * 10) / 10} 天，建议评估该平台供应商发货速度和物流渠道，考虑换用更高效的供应商或物流方式。`,
    });
  }

  // 建议3：异常率分析
  const abnormalCount = records.filter(
    (r) => r.arrivalQuality === 'damaged' || r.arrivalQuality === 'defective' || r.arrivalQuality === 'missing',
  ).length;
  const abnormalRate = arrivedRecords.length > 0 ? abnormalCount / arrivedRecords.length : 0;

  if (abnormalRate > 0.2) {
    suggestions.push({
      type: 'warning',
      icon: 'trending-up',
      title: `异常率偏高（${Math.round(abnormalRate * 100)}%）`,
      content: `到货异常率超过20%（${abnormalCount}/${arrivedRecords.length}单），建议排查供应链各环节：供应商质检、包装质量、物流搬运等，针对性改进。`,
    });
  } else if (abnormalRate > 0.1) {
    suggestions.push({
      type: 'info',
      icon: 'lightbulb',
      title: `异常率 ${Math.round(abnormalRate * 100)}%，需关注`,
      content: '存在一定比例的到货异常，建议重点记录异常类型和原因，积累数据后针对性优化供应商或物流选择。',
    });
  }

  // 建议4：备货建议（基于时效最长的品类）
  if (arrivedRecords.length >= 5 && avgDays > 10) {
    suggestions.push({
      type: 'info',
      icon: 'target',
      title: '建议提前备货',
      content: '考虑到整体时效较长，建议对热销产品提前15-20天下单备货，避免断货风险；同时可建立安全库存机制，应对物流波动。',
    });
  }

  return suggestions;
}

// ==================== 工具函数 ====================

function genId(): string {
  return 'po_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
}

function formatDate(date: string | Date): string {
  const d = typeof date === 'string' ? new Date(date) : date;
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  const h = String(d.getHours()).padStart(2, '0');
  const min = String(d.getMinutes()).padStart(2, '0');
  return `${y}-${m}-${day} ${h}:${min}`;
}

function getStatusMeta(status: OrderStatus) {
  return ORDER_STATUS.find((s) => s.key === status) || ORDER_STATUS[0];
}

function getStatusIndex(status: OrderStatus): number {
  return ORDER_STATUS.findIndex((s) => s.key === status);
}

function nextStatus(current: OrderStatus): OrderStatus | null {
  const idx = getStatusIndex(current);
  if (idx < 0 || idx >= ORDER_STATUS.length - 2) return null; // 排除异常
  return ORDER_STATUS[idx + 1].key;
}

// ==================== 物流查询（17track 真实接口 + Mock 降级） ====================

const DEFAULT_17TRACK_KEY = 'BB51C787D092993CBA780AE40FA42BE5';

async function queryLogistics(
  trackingNumber: string,
  config: LogisticsConfig,
): Promise<LogisticsQueryResult> {
  if (!trackingNumber || trackingNumber.trim().length < 5) {
    return {
      success: false,
      status: null,
      traces: [],
      errorMsg: '运单号太短或无效',
    };
  }

  // 未配置密钥 → 返回提示
  if (!isConfigValid(config)) {
    return mockQueryLogistics(trackingNumber);
  }

  // 17track 真实接口调用
  try {
    const apiKey = config.apiKey || DEFAULT_17TRACK_KEY;
    const result = await query17Track(trackingNumber, apiKey);
    return result;
  } catch (err) {
    logger.error('17track 物流查询失败:', String(err));
    // 查询失败时降级到 mock
    return mockQueryLogistics(trackingNumber);
  }
}

function isConfigValid(config: LogisticsConfig): boolean {
  if (config.provider === '17track') {
    return !!(config.apiKey && config.apiKey.trim().length > 0);
  }
  return false;
}

// 17track 状态码 → 本地状态映射
// https://www.17track.net/en/api-doc#states
function map17TrackStatus(status: number): OrderStatus {
  switch (status) {
    case 1: // 已揽收/已发货
      return 'shipped';
    case 2: // 运输中
    case 3: // 到达待取
    case 10: // 到达投递局
      return 'in_transit';
    case 4: // 已签收/成功投递
      return 'arrived';
    case 5: // 投递失败
    case 6: // 退回
    case 7: // 异常
    case 12: // 滞留件
    case 13: // 销毁
      return 'abnormal';
    case 0: // 查询不到 / 无信息
    case 8: // 运输过久
    case 9: // 可能异常
    case 11: // 已签收（但可能是代收）
    default:
      return 'in_transit';
  }
}

function format17TrackTime(t: string): string {
  // 17track 返回的时间格式通常为 "2024-01-15 10:30"
  if (!t) return '';
  // 如果已经是 YYYY-MM-DD HH:mm 格式直接返回
  if (/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}/.test(t)) return t;
  const d = new Date(t);
  if (!isNaN(d.getTime())) return formatDate(d);
  return t;
}

async function query17Track(
  trackingNumber: string,
  apiKey: string,
): Promise<LogisticsQueryResult> {
  // 第一步：注册单号
  const registerBody = {
    tracking_numbers: [
      {
        number: trackingNumber.trim(),
      },
    ],
  };

  try {
    const registerRes = await fetch('https://api.17track.net/track/v2.2/register', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify(registerBody),
    });

    if (!registerRes.ok) {
      logger.warn(`17track register HTTP ${registerRes.status}`);
    }
    // 注册失败不阻塞查询，继续调 track 接口
  } catch (err) {
    logger.warn('17track register 调用异常（继续查询）:', String(err));
  }

  // 第二步：查询轨迹
  const trackBody = {
    tracking_numbers: [
      {
        number: trackingNumber.trim(),
      },
    ],
  };

  const trackRes = await fetch('https://api.17track.net/track/v2.2/track', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify(trackBody),
  });

  if (!trackRes.ok) {
    throw new Error(`17track track HTTP ${trackRes.status}`);
  }

  const data = await trackRes.json();

  // 解析返回结构
  // accepted: [{ number, carrier, status, track_info: { events: [{ time, location, desc }] } }]
  // rejected: [{ number, ... }]
  const accepted = data?.accepted || [];
  const rejected = data?.rejected || [];

  if (rejected && rejected.length > 0) {
    const reason = rejected[0]?.error?.message || '单号无法识别或不支持该快递商';
    throw new Error(reason);
  }

  if (!accepted || accepted.length === 0) {
    throw new Error('未查询到物流信息');
  }

  const item = accepted[0];
  const statusCode = item.status || 0;
  const carrier = item.carrier || '';
  const events = item?.track_info?.event || [];

  // 轨迹按时间倒序（最新在前），我们转为正序（最旧在前）展示时间轴
  const traces: LogisticsTrace[] = [...events]
    .sort((a: { time: string }, b: { time: string }) => {
      const ta = new Date(a.time).getTime();
      const tb = new Date(b.time).getTime();
      return tb - ta; // 最新在前
    })
    .map((e: { time: string; location: string; desc: string }) => ({
      time: format17TrackTime(e.time),
      location: e.location || '',
      desc: e.desc || '',
    }));

  const latestTime = traces.length > 0 ? traces[0].time : undefined;
  const mappedStatus = map17TrackStatus(statusCode);
  // 状态描述补充：如果 carrier 里有名称，拼到一起
  const carrierName = item?.carrier_name?.['zh-CN'] || carrier || '未知快递';

  return {
    success: true,
    status: mappedStatus,
    carrier: carrierName,
    latestTime,
    traces,
  };
}

